css:
.cyclesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8e2d8;
    background: linear-gradient(160deg, #1c1a17 0%, #14130f 55%, #0d0c09 100%);
    border-radius: 16px;
}

.cyclesim-container * {
    box-sizing: border-box;
}

.cyclesim-header {
    text-align: center;
    padding: 28px 20px 24px;
    background: linear-gradient(135deg, #241f18 0%, #3a2a17 55%, #5a3410 100%);
    color: #fbf3e6;
    border-radius: 14px;
    margin-bottom: 20px;
    border: 1px solid #4a3a25;
    border-top: 4px solid #ff7a1a;
    box-shadow: 0 14px 36px rgba(0, 0, 0, 0.55);
}

.cyclesim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: #ffb066;
    text-shadow: 0 2px 10px rgba(255, 122, 26, 0.35);
}

.cyclesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #ffb066;
    background: rgba(255, 122, 26, 0.12);
    border: 1px solid rgba(255, 122, 26, 0.35);
    padding: 5px 14px;
    border-radius: 4px;
}

.cyclesim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d8cdba;
}

.cyclesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #b3a892;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.cyclesim-period-counter #currentDay,
.cyclesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #ff924a;
}

.cyclesim-round-name {
    background: rgba(255, 146, 74, 0.14);
    color: #ff924a;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.82rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-left: 4px;
}

.cyclesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffd089;
    background: rgba(255, 208, 137, 0.10);
    border: 1px solid rgba(255, 208, 137, 0.30);
    padding: 4px 12px;
    border-radius: 4px;
}

.cyclesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cyclesim-status-card {
    background: linear-gradient(160deg, #211e18 0%, #17150f 100%);
    border-radius: 10px;
    padding: 16px 16px 14px;
    border: 1px solid #3a3326;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.40);
    border-left: 4px solid #6b5d44;
}

.cyclesim-card-roic { border-left-color: #5fc8e0; }
.cyclesim-card-survival { border-left-color: #6ee07a; }
.cyclesim-card-leverage { border-left-color: #ffb066; }
.cyclesim-card-position { border-left-color: #c79bff; }

.cyclesim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    font-weight: 700;
    color: #9a8e76;
}

.cyclesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #fbf3e6;
    font-variant-numeric: tabular-nums;
}

.cyclesim-card-roic .cyclesim-value { color: #5fc8e0; }
.cyclesim-card-survival .cyclesim-value { color: #6ee07a; }
.cyclesim-card-leverage .cyclesim-value { color: #ffb066; }
.cyclesim-card-position .cyclesim-value { color: #c79bff; }

.cyclesim-sublabel {
    font-size: 0.75rem;
    color: #8f846f;
    line-height: 1.35;
}

/* Survival low / leverage breach state telegraphing. */
.cyclesim-survival-low { border-left-color: #ff4d4d; }
.cyclesim-survival-low .cyclesim-value { color: #ff5c5c; }
.cyclesim-survival-high { border-left-color: #6ee07a; }
.cyclesim-survival-high .cyclesim-value { color: #6ee07a; }

.cyclesim-leverage-breach { border-left-color: #ff4d4d; }
.cyclesim-leverage-breach .cyclesim-value { color: #ff5c5c; }
.cyclesim-leverage-safe .cyclesim-value { color: #6ee07a; }

.cyclesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #16140f;
    border: 1px solid #3a3326;
    border-left: 4px solid #ffb066;
    color: #d8cdba;
    padding: 10px 18px;
    border-radius: 8px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.cyclesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ffb066;
}

.cyclesim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #211e18 0%, #17150f 100%);
    border-left: 5px solid #ff7a1a;
    border-radius: 8px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
}

.cyclesim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.cyclesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffb066;
    margin-bottom: 6px;
}

.cyclesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #d4c9b6;
}

.cyclesim-briefing-text strong { color: #ffb066; }
.cyclesim-briefing-text em { color: #5fc8e0; font-style: italic; }

.cyclesim-controls {
    background: linear-gradient(160deg, #1d1a14 0%, #15130e 100%);
    border-radius: 10px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #3a3326;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
}

.cyclesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: #fbf3e6;
    border-bottom: 2px solid #3a3326;
    padding-bottom: 8px;
}

.cyclesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #d4c9b6;
    margin: 14px 0 6px;
}

.cyclesim-container select,
.cyclesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #4a4030;
    border-radius: 6px;
    font-size: 0.92rem;
    background-color: #14120d;
    color: #f0e7d6;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cyclesim-container select:focus,
.cyclesim-container input[type="number"]:focus {
    outline: none;
    border-color: #ff924a;
    box-shadow: 0 0 0 3px rgba(255, 146, 74, 0.20);
}

.cyclesim-container select option {
    background-color: #14120d;
    color: #f0e7d6;
}

.cyclesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #ff7a1a;
}

.cyclesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #b3a892;
    margin-top: 4px;
}

.cyclesim-range-readout span:nth-child(2) {
    color: #ff924a;
    font-weight: 800;
}

.cyclesim-covenant-note {
    color: #8f846f !important;
    font-weight: 600 !important;
    font-size: 0.82rem;
}

.cyclesim-hint {
    font-size: 0.8rem;
    color: #8f846f;
    margin-top: 4px;
    line-height: 1.4;
}

.cyclesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cyclesim-container .btn-primary {
    background: linear-gradient(135deg, #c2480a 0%, #ff7a1a 100%);
    border: none;
    color: #1c1208;
    padding: 11px 28px;
    border-radius: 6px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    box-shadow: 0 8px 20px rgba(255, 122, 26, 0.35);
}

.cyclesim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.cyclesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #4a4030;
    color: #b3a892;
    background: transparent;
}

.cyclesim-coach {
    background: linear-gradient(160deg, #16140f 0%, #1a1410 100%);
    color: #e0d6c4;
    border: 1px solid #4a3a25;
    border-left: 5px solid #ffd089;
    border-radius: 10px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
}

.cyclesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd089;
    margin-bottom: 8px;
}

.cyclesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cyclesim-coach-body strong { color: #ffb066; }
.cyclesim-coach-body em { color: #5fc8e0; font-style: italic; }

.cyclesim-history,
.cyclesim-chart {
    background: linear-gradient(160deg, #1d1a14 0%, #15130e 100%);
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #3a3326;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
}

.cyclesim-history h3,
.cyclesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #fbf3e6;
}

.cyclesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #d4c9b6;
}

.cyclesim-container table#usfHistoryTable th {
    background: #14120d;
    color: #ffb066;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #4a4030;
}

.cyclesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #2a2519;
    color: #cabfac;
}

.cyclesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #17150f;
}

.cyclesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cyclesim-container {
        padding: 14px;
    }
    .cyclesim-header h1 {
        font-size: 1.7rem;
    }
    .cyclesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cyclesim-value {
        font-size: 2rem;
    }
    .cyclesim-clock {
        margin-left: 0;
    }
    .cyclesim-period-counter {
        font-size: 0.88rem;
    }
    .cyclesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .cyclesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (cyclesim) ---- */
.cyclesim-completion { padding: 8px 4px 4px; }
.cyclesim-cm-head { text-align: center; margin-bottom: 16px; }
.cyclesim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #b5762a; }
.cyclesim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #d0a875; }
.cyclesim-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #33291a; }
.cyclesim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.cyclesim-cm-yes { background: rgba(181,118,42,0.16); color: #b5762a; border: 1px solid rgba(181,118,42,0.5); }
.cyclesim-cm-no { background: rgba(180,70,55,0.12); color: #a5412c; border: 1px solid rgba(180,70,55,0.45); }
.cyclesim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.cyclesim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(181,118,42,0.08); border: 1px solid rgba(181,118,42,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.cyclesim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #b5762a; }
.cyclesim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #656b7c; text-transform: uppercase; letter-spacing: 0.03em; }
.cyclesim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #33291a; }
.cyclesim-cm-insights { margin: 0; padding-left: 20px; }
.cyclesim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #363c4b; }

