(function() {
    'use strict';

    class CycleAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Cycle Strategist`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card — Aceros del Plata S.A.
            this.CAPEX_USD = 140;          // US$140M expansion (AR$168,000M)
            this.ACQ_USD = 60;             // US$60M distressed-rival acquisition
            this.COVENANT = 3.5;           // 3.5x net-leverage covenant
            this.START_LEVERAGE = 1.4;     // 1.4x net leverage entering the peak
            this.PEAK_PROFORMA = 3.4;      // ~3.4x on peak EBITDA, all-debt
            this.TROUGH_PROFORMA = 5.0;    // ~5.0x on trough EBITDA, all-debt
            this.START_ROIC = 12;          // 12% mid-cycle ROIC
            this.DRY_POWDER_START = 40;    // US$M cash / liquidity entering the decision

            // Concept truths (the cycle-aware play).
            this.TRUE_CYCLE = `peak`;
            this.TRUE_BASIS = `trough`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    roic: 12,              // % ROIC
                    survival: 70,          // downside survival probability (0–100)
                    leverage: 1.4,         // net leverage on TROUGH EBITDA (x)
                    position: 50,          // strategic position (0–100)
                    dryPowder: 40,         // US$M liquidity buffer / dry powder
                    covenantBreached: false,
                    capacityCommitted: false,
                    unhedged: false,
                    optionAlive: true,
                    roicHistory: [12],
                    survivalHistory: [70],
                    leverageHistory: [1.4],
                    positionHistory: [50],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately PEAK-CHASING / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    cycle: `peak`,
                    signals: `some`,
                    prob: 50,
                    capacity: `approve`,
                    slot: `rush`,
                    basis: `peak`,
                    finance: `usd`,
                    ceiling: 35,
                    buffer: 0,
                    hedge: `unhedged`,
                    move: `match`,
                    reconcile: `hope`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const cy = document.getElementById(`cycleInput`);
                const sg = document.getElementById(`signalsInput`);
                const pr = document.getElementById(`probInput`);
                if (cy) decisions.cycle = cy.value;
                if (sg) decisions.signals = sg.value;
                if (pr) decisions.prob = parseInt(pr.value, 10);
                if (!Number.isFinite(decisions.prob) || decisions.prob < 0 || decisions.prob > 100) {
                    warn(`warn_prob_range`); return false;
                }
            } else if (round === 2) {
                const cp = document.getElementById(`capacityInput`);
                const sl = document.getElementById(`slotInput`);
                const bs = document.getElementById(`basisInput`);
                if (cp) decisions.capacity = cp.value;
                if (sl) decisions.slot = sl.value;
                if (bs) decisions.basis = bs.value;
                if (!decisions.capacity || !decisions.basis) {
                    warn(`warn_capacity_required`); return false;
                }
            } else if (round === 3) {
                const fn = document.getElementById(`financeInput`);
                const cl = document.getElementById(`ceilingInput`);
                const bf = document.getElementById(`bufferInput`);
                const hg = document.getElementById(`hedgeInput`);
                if (fn) decisions.finance = fn.value;
                if (cl) decisions.ceiling = parseInt(cl.value, 10);   // stored as tenths (e.g. 35 → 3.5x)
                if (bf) decisions.buffer = parseFloat(bf.value);
                if (hg) decisions.hedge = hg.value;
                if (!Number.isFinite(decisions.ceiling) || decisions.ceiling < 20 || decisions.ceiling > 50) {
                    warn(`warn_ceiling_range`); return false;
                }
                if (!Number.isFinite(decisions.buffer) || decisions.buffer < 0) {
                    warn(`warn_buffer_value`); return false;
                }
            } else if (round === 4) {
                const mv = document.getElementById(`moveInput`);
                const rc = document.getElementById(`reconcileInput`);
                const cv = document.getElementById(`convictionInput`);
                if (mv) decisions.move = mv.value;
                if (rc) decisions.reconcile = rc.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let roicDelta = 0, survivalDelta = 0, leverageDelta = 0, positionDelta = 0, powderDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Read the cycle (Common Error 2: extrapolating peak demand as trend).
                switch (d.cycle) {
                    case `peak`: survivalDelta += 10; positionDelta += 6; coachKey = `coach_r1_peak`; break;
                    case `midcycle`: survivalDelta -= 4; positionDelta -= 2; coachKey = `coach_r1_mid`; break;
                    case `early`: survivalDelta -= 8; positionDelta -= 4; coachKey = `coach_r1_early`; break;
                }

                // Which leading indicators ground the downturn scenario.
                switch (d.signals) {
                    case `all`: survivalDelta += 8; positionDelta += 4; if (d.cycle === `peak`) coachKey = `coach_r1_sharp`; break;
                    case `some`: survivalDelta += 2; break;
                    case `none`: survivalDelta -= 10; positionDelta -= 4; coachKey = `coach_r1_none`; break;
                }

                // Stated probability of a near-term downturn (intel view: high).
                if (d.prob >= 60) { survivalDelta += 5; positionDelta += 2; }
                else if (d.prob <= 25) { survivalDelta -= 6; positionDelta -= 2; coachKey = `coach_r1_lowprob`; }

                summaryKey = (d.cycle === `peak` && d.signals === `all` && d.prob >= 50) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Time the capacity investment (Common Error 1: full capacity at the peak).
                switch (d.capacity) {
                    case `approve`:
                        // Commissions into the trough at ~55% utilization → ROIC collapse.
                        ds.capacityCommitted = true;
                        roicDelta -= 8; leverageDelta += 1.8; survivalDelta -= 14; positionDelta += 6; powderDelta -= 20;
                        coachKey = `coach_r2_approve`;
                        break;
                    case `phase`:
                        // Real option: furnace upgrade now, rolling line held — flexibility under uncertainty.
                        ds.capacityCommitted = true;
                        roicDelta -= 1; leverageDelta += 0.6; survivalDelta += 4; positionDelta += 8; powderDelta -= 7;
                        coachKey = `coach_r2_phase`;
                        break;
                    case `defer`:
                        // Build at the bottom into the next upswing — cheaper, but slot risk.
                        roicDelta += 2; survivalDelta += 8; positionDelta += 3;
                        coachKey = `coach_r2_defer`;
                        break;
                    case `decline`:
                        // No new capacity at all — safe on ROIC, but capacity-short in the next upswing.
                        roicDelta += 1; survivalDelta += 5; positionDelta -= 4;
                        coachKey = `coach_r2_decline`;
                        break;
                }

                // 45-day slot: refundable deposit preserves the option; a rushed full sign-up burns flexibility.
                switch (d.slot) {
                    case `secure`: positionDelta += 5; survivalDelta += 2; break;
                    case `rush`: if (d.capacity === `approve`) { survivalDelta -= 4; leverageDelta += 0.3; } positionDelta += 1; coachKey = (d.capacity === `approve`) ? `coach_r2_rush` : coachKey; break;
                    case `lapse`: if (d.capacity === `defer` || d.capacity === `decline`) { positionDelta -= 2; } else { positionDelta -= 5; survivalDelta -= 2; } break;
                }

                // Which EBITDA the NPV/ROIC runs against (Common Error 3 foreshadowed).
                switch (d.basis) {
                    case `trough`: survivalDelta += 10; positionDelta += 4; if (coachKey === `coach_r2_approve`) coachKey = `coach_r2_troughbasis`; break;
                    case `midcycle`: survivalDelta += 3; break;
                    case `peak`: survivalDelta -= 8; positionDelta -= 2; coachKey = `coach_r2_peakbasis`; break;
                }

                summaryKey = ((d.capacity === `phase` || d.capacity === `defer`) && d.basis !== `peak`) ? `sum_r2_good` :
                             (d.capacity === `approve` && d.basis === `peak` ? `sum_r2_peakbuild` : `sum_r2_weak`);
            } else if (round === 3) {
                // Set the financial posture (Common Error 3: debt to peak EBITDA → breach).
                const committed = ds.capacityCommitted;

                switch (d.finance) {
                    case `balanced`: survivalDelta += 8; positionDelta += 4; if (committed) leverageDelta += 0.7; coachKey = `coach_r3_balanced`; break;
                    case `usd`: roicDelta += 2; if (committed) { leverageDelta += 2.0; survivalDelta -= 12; } else { leverageDelta += 0.8; survivalDelta -= 4; } coachKey = `coach_r3_usd`; break;
                    case `local`: roicDelta -= 3; if (committed) leverageDelta += 1.4; survivalDelta -= 2; positionDelta += 1; coachKey = `coach_r3_local`; break;
                    case `cash`: leverageDelta -= 0.3; survivalDelta += 4; positionDelta -= 4; powderDelta -= 25; coachKey = `coach_r3_cash`; break;
                }

                // Leverage ceiling judged on TROUGH EBITDA. Tighter is more survivable here.
                const ceilingX = d.ceiling / 10;
                if (ceilingX <= 3.0) { survivalDelta += 9; positionDelta += 2; }
                else if (ceilingX <= this.COVENANT) { survivalDelta += 4; }
                else { survivalDelta -= 8; positionDelta -= 2; coachKey = `coach_r3_loose`; }

                // Minimum liquidity buffer / dry powder, sized to the downside (Common Error 5 link to R4).
                powderDelta += d.buffer;
                if (d.buffer >= 70) { survivalDelta += 10; positionDelta += 6; }
                else if (d.buffer >= 30) { survivalDelta += 4; positionDelta += 2; }
                else { survivalDelta -= 6; positionDelta -= 4; ds.optionAlive = false; coachKey = (coachKey === `coach_default`) ? `coach_r3_nobuffer` : coachKey; }

                // FX hedging on US$-priced CapEx against AR$ revenues (Common Error 5).
                switch (d.hedge) {
                    case `hedge`: survivalDelta += 8; positionDelta += 2; break;
                    case `partial`: survivalDelta += 2; break;
                    case `unhedged`: if (committed || d.finance === `usd`) { survivalDelta -= 12; leverageDelta += 0.5; ds.unhedged = true; coachKey = `coach_r3_unhedged`; } else { survivalDelta -= 4; } break;
                }

                summaryKey = (ceilingX <= this.COVENANT && d.buffer >= 30 && d.hedge !== `unhedged` && d.finance !== `usd`) ? `sum_r3_good` :
                             ((d.finance === `usd` && committed) || d.hedge === `unhedged` ? `sum_r3_fragile` : `sum_r3_weak`);
            } else if (round === 4) {
                // Make the competitive move (Common Error 4: hoard cash, forfeit the acquisition).
                const haveDryPowder = ds.dryPowder >= this.ACQ_USD;
                const headroom = ds.leverage <= this.COVENANT;

                switch (d.move) {
                    case `acquire`:
                        if (haveDryPowder && headroom) {
                            // Pre-committed capacity to act at the bottom — the counter-cyclical win.
                            positionDelta += 18; roicDelta += 4; survivalDelta += 2; powderDelta -= this.ACQ_USD;
                            coachKey = `coach_r4_acquirewin`;
                        } else {
                            // Right instinct, no means — the option was pre-spent.
                            positionDelta += 4; survivalDelta -= 8; leverageDelta += 0.8;
                            coachKey = `coach_r4_acquirenomeans`;
                        }
                        break;
                    case `match`:
                        // Capacity-for-capacity at the peak — escalation into the trough.
                        positionDelta += 6; roicDelta -= 5; survivalDelta -= 10; leverageDelta += 1.0;
                        coachKey = `coach_r4_match`;
                        break;
                    case `defend`:
                        // Hold and defend share on cost/service — solid, unspectacular.
                        positionDelta += 6; roicDelta += 2; survivalDelta += 4;
                        coachKey = `coach_r4_defend`;
                        break;
                    case `retreat`:
                        // Fortress balance sheet, no move — forfeits the counter-cyclical opportunity.
                        survivalDelta += 4; positionDelta -= 12; roicDelta -= 1;
                        coachKey = `coach_r4_retreat`;
                        break;
                }

                // Does the move reconcile with the leverage / liquidity already set?
                switch (d.reconcile) {
                    case `precommitted`: positionDelta += 6; survivalDelta += 4; if (d.move === `acquire` && haveDryPowder && headroom) coachKey = `coach_r4_integrated`; break;
                    case `hope`: positionDelta -= 2; survivalDelta -= 3; break;
                    case `ignore`: positionDelta -= 4; survivalDelta -= 6; leverageDelta += 0.3; coachKey = `coach_r4_ignore`; break;
                }

                if (d.conviction >= 60) { positionDelta += 4; survivalDelta += 2; }
                else if (d.conviction <= 25) { positionDelta -= 4; survivalDelta -= 2; }

                summaryKey = (d.move === `acquire` && haveDryPowder && headroom) ? `sum_r4_good` :
                             (d.move === `retreat` ? `sum_r4_retreat` : `sum_r4_weak`);
            }

            // Apply deltas with clamps.
            ds.roic = Math.round((ds.roic + roicDelta) * 10) / 10;
            ds.survival = Math.max(0, Math.min(100, Math.round(ds.survival + survivalDelta)));
            ds.leverage = Math.max(0, Math.round((ds.leverage + leverageDelta) * 10) / 10);
            ds.position = Math.max(0, Math.min(100, Math.round(ds.position + positionDelta)));
            ds.dryPowder = Math.max(0, Math.round(ds.dryPowder + powderDelta));

            // Covenant test on trough leverage.
            if (ds.leverage > this.COVENANT) {
                ds.covenantBreached = true;
                if (round >= 3 && coachKey === `coach_default`) coachKey = `coach_breach`;
            }

            ds.roicHistory.push(ds.roic);
            ds.survivalHistory.push(ds.survival);
            ds.leverageHistory.push(ds.leverage);
            ds.positionHistory.push(ds.position);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                roic: ds.roic,
                roicDelta: Math.round(roicDelta * 10) / 10,
                survival: ds.survival,
                survivalDelta: Math.round(survivalDelta),
                leverage: ds.leverage,
                leverageDelta: Math.round(leverageDelta * 10) / 10,
                position: ds.position,
                positionDelta: Math.round(positionDelta),
                dryPowder: ds.dryPowder,
                covenantBreached: ds.covenantBreached,
                unhedged: ds.unhedged,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtUSD(v) {
            // US$ kept VISUALLY DISTINCT from AR$ — always the "US$" prefix.
            const sign = v < 0 ? `-` : ``;
            return `${sign}US$${Math.abs(Math.round(v))}M`;
        }

        _fmtLeverage(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            return (lang === `es` ? s.replace(`.`, `,`) : s) + `x`;
        }

        _fmtRoic(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(0);
            return (lang === `es` ? `${s}%` : `${s}%`);
        }

