            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`roicDisplay`, `domainState.roic`, (v) => self._fmtRoic(Number(v)));
            uiManager.bind(`survivalDisplay`, `domainState.survival`, (v) => {
                const card = document.querySelector(`.cyclesim-card-survival`);
                if (card) {
                    card.classList.toggle(`cyclesim-survival-low`, Number(v) <= 40);
                    card.classList.toggle(`cyclesim-survival-high`, Number(v) >= 75);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`leverageDisplay`, `domainState.leverage`, (v) => {
                const card = document.querySelector(`.cyclesim-card-leverage`);
                if (card) {
                    card.classList.toggle(`cyclesim-leverage-breach`, Number(v) > self.COVENANT);
                    card.classList.toggle(`cyclesim-leverage-safe`, Number(v) <= self.COVENANT);
                }
                return self._fmtLeverage(Number(v));
            });
            uiManager.bind(`positionDisplay`, `domainState.position`, (v) => Math.round(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.dryPowder`, (v) => self._fmtUSD(Number(v)));

            // Probability slider readout.
            const pr = document.getElementById(`probInput`);
            const prReadout = document.getElementById(`probReadout`);
            if (pr && prReadout) {
                prReadout.textContent = pr.value;
                pr.addEventListener(`input`, function() { prReadout.textContent = pr.value; });
            }

            // Leverage-ceiling slider readout (stored as tenths; shown as Nx).
            const cl = document.getElementById(`ceilingInput`);
            const clReadout = document.getElementById(`ceilingReadout`);
