                const x = (parseInt(cl.value, 10) / 10);
                const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
                clReadout.textContent = (lang === `es` ? x.toFixed(1).replace(`.`, `,`) : x.toFixed(1));
                clReadout.style.color = (x > self.COVENANT) ? `#ff5c5c` : `#ff924a`;
            };
            if (cl && clReadout) {
                renderCeiling();
                cl.addEventListener(`input`, renderCeiling);
            }
        }

