        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.survivalHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                cycleChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.survivalHistory },
                        { data: ds.positionHistory },
                        { data: ds.leverageHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const roic = Math.round(ds.roic);
            const survival = Math.round(ds.survival);
            const leverage = ds.leverage;
            const position = Math.round(ds.position);
            const leverScore = Math.max(0, Math.min(100, (this.COVENANT - leverage) / this.COVENANT * 100 + 50));
            const roicScore = Math.max(0, Math.min(100, roic * 5));
            return Math.max(0, Math.min(100, Math.round(survival * 0.38 + position * 0.27 + roicScore * 0.18 + leverScore * 0.17)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const roic = Math.round(ds.roic);
            const survival = Math.round(ds.survival);
            const leverage = ds.leverage;
            const position = Math.round(ds.position);

            // Composite: survival is the binding objective, then position, ROIC and leverage discipline.
            const composite = this._composite(ds);

            const survived = survival >= 55 && !ds.covenantBreached;
            const counterCyclical = ds.dryPowder >= this.ACQ_USD || (position >= 70 && survived);
            const breached = ds.covenantBreached || leverage > this.COVENANT;

            let performance = window.mySimulation.t(`grade_caught`);
            if (survived && counterCyclical && composite >= 75) performance = window.mySimulation.t(`grade_bottom`);
            else if (survived && composite >= 60) performance = window.mySimulation.t(`grade_trough`);
            else if (breached) performance = window.mySimulation.t(`grade_breach`);
            else if (position <= 30 && survival >= 60) performance = window.mySimulation.t(`grade_sidelined`);
            else if (composite >= 50) performance = window.mySimulation.t(`grade_mixed`);

            const insights = [];
            if (survived && counterCyclical) insights.push(window.mySimulation.t(`insight_bottom`));
            else if (breached) insights.push(window.mySimulation.t(`insight_breach`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (leverage > this.COVENANT) insights.push(window.mySimulation.t(`insight_leverage`));
            else if (leverage <= 2.0) insights.push(window.mySimulation.t(`insight_resilient`));
            if (ds.unhedged) insights.push(window.mySimulation.t(`insight_unhedged`));
            if (position <= 30) insights.push(window.mySimulation.t(`insight_sidelined`));
            if (roic <= 5) insights.push(window.mySimulation.t(`insight_roic`));
            if (survived && counterCyclical && roic >= 12) insights.push(window.mySimulation.t(`insight_weapon`));

            return {
                roic: roic,
                survival: survival,
                leverage: leverage,
                position: position,
                survived: survived,
                counterCyclical: counterCyclical,
                breached: breached,
                met: (survived && counterCyclical && composite >= 75),
                notSurvived: !survived,
                sidelined: (position <= 30),
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="cyclesim-cm-badge cyclesim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="cyclesim-cm-badge cyclesim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.breached) failBadge += ` <span class="cyclesim-cm-badge cyclesim-cm-no">` + T(`cm_breach`) + `</span>`;
            if (s.notSurvived) failBadge += ` <span class="cyclesim-cm-badge cyclesim-cm-no">` + T(`cm_notsurvived`) + `</span>`;
            if (s.sidelined) failBadge += ` <span class="cyclesim-cm-badge cyclesim-cm-no">` + T(`cm_sidelined`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="cyclesim-cm-metric"><span class="cyclesim-cm-mv">` + (Math.round(s.roic || 0) + `%`) + `</span><span class="cyclesim-cm-ml">` + T(`cm_m_roic`) + `</span></div>`
                + `<div class="cyclesim-cm-metric"><span class="cyclesim-cm-mv">` + Math.round(s.survival || 0) + `</span><span class="cyclesim-cm-ml">` + T(`cm_m_survival`) + `</span></div>`
                + `<div class="cyclesim-cm-metric"><span class="cyclesim-cm-mv">` + ((Math.round((s.leverage || 0) * 10) / 10) + `x`) + `</span><span class="cyclesim-cm-ml">` + T(`cm_m_leverage`) + `</span></div>`
                + `<div class="cyclesim-cm-metric"><span class="cyclesim-cm-mv">` + Math.round(s.position || 0) + `</span><span class="cyclesim-cm-ml">` + T(`cm_m_position`) + `</span></div>`;
            return ``
                + `<div class="cyclesim-completion">`
                +   `<div class="cyclesim-cm-head">`
                +     `<div class="cyclesim-cm-score">` + score + `<span class="cyclesim-cm-score-max">/100</span></div>`
                +     `<div class="cyclesim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="cyclesim-cm-metrics">` + metrics + `</div>`
                +   `<div class="cyclesim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="cyclesim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.covenantBreached) return window.mySimulation.t(`hint_breach`);
            if (ds.unhedged) return window.mySimulation.t(`hint_unhedged`);
            if (ds.survival <= 40) return window.mySimulation.t(`hint_survival`);
            if (state.currentPeriod >= 3 && ds.dryPowder < this.ACQ_USD) return window.mySimulation.t(`hint_powder`);
            if (ds.roic <= 5 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_roic`);
            if (ds.survival >= 70 && ds.leverage <= 2.5 && ds.position >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

